import csv, json
from collections import defaultdict
from pathlib import Path

SUPPORTED = {"ip", "domain", "sha256"}
rows = []
for row in csv.DictReader(Path("iocs.csv").open(newline="", encoding="utf-8")):
    kind = row["type"].strip().lower()
    value = row["value"].strip()
    if kind not in SUPPORTED or not value:
        continue
    rows.append({"type": kind, "value": value, "source": row["source"].strip(), "timestamp": row["timestamp"].strip()})

merged = defaultdict(list)
for row in rows:
    key = (row["type"], row["value"])
    merged[key].append({"source": row["source"], "timestamp": row["timestamp"]})

queue = [
    {"type": k[0], "value": k[1], "observations": v}
    for k, v in sorted(merged.items())
]
Path("review_queue.json").write_text(json.dumps(queue, indent=2), encoding="utf-8")
print(f"Wrote {len(queue)} unique indicators to review_queue.json")
